<!doctype html><html><head><meta charset="utf-8"><style>@page{size:A4 portrait;margin:8mm}*{box-sizing:border-box}body{margin:0;font-family:Arial;color:#12344f}.layout{width:100%;border-collapse:collapse;table-layout:fixed}.layout>tbody>tr{page-break-inside:avoid}.slot{width:50%;padding:0 5mm 10mm 0;vertical-align:top}.slot.right{padding-right:0;padding-left:5mm}.student-card{width:85.6mm;height:53.98mm;overflow:hidden;position:relative;border:1px solid #8fd2e7;border-radius:3mm;background:#c9f3fc;background-image:linear-gradient(155deg,rgba(255,255,255,.75) 0 29%,transparent 29%),linear-gradient(25deg,rgba(31,184,218,.18) 0 24%,transparent 24%),linear-gradient(115deg,#dffaff,#b8ebf7 58%,#d8f8fb);-webkit-print-color-adjust:exact;print-color-adjust:exact}.shape{position:absolute;width:45mm;height:45mm;right:-19mm;top:-23mm;border-radius:50%;background:#0a9bc21f}.header{height:16.5mm;padding:2.4mm 3.5mm 1.8mm;border-bottom:.65mm solid #65bed9;position:relative;z-index:2}.tbl{width:100%;border-collapse:collapse}.logo{width:11.5mm;vertical-align:middle}.logo img{width:9.5mm;height:9.5mm;object-fit:contain}.school{vertical-align:middle}.school b{display:block;font-size:2.3mm;line-height:1.1;text-transform:uppercase}.school small{display:block;margin-top:.6mm;font-size:1.55mm;color:#47768c}.title{text-align:right;color:#087ead;vertical-align:middle;white-space:nowrap}.title b{display:block;font-size:4.2mm;line-height:1}.title small{display:block;margin-top:1mm;font-size:1.25mm;font-weight:bold;letter-spacing:.08em}.content{height:37.48mm;padding:3mm 3.5mm;position:relative;z-index:2}.photo{width:17mm;height:23mm;object-fit:cover;border:.7mm solid #fff;border-radius:1.3mm;background:#fff}.data{padding:0 2.3mm;vertical-align:middle}.data table{width:100%;font-size:2.05mm;line-height:1.6}.data td:first-child{width:15mm;white-space:nowrap}.data td:last-child{font-weight:bold;white-space:nowrap}.qr{text-align:right;vertical-align:bottom;width:20mm}.qrbox{display:inline-block;width:18.5mm;height:18.5mm;padding:1.15mm;background:#fff;border:1px solid #8cc9dc;border-radius:1.3mm}.qrbox img{width:16mm;height:16mm;display:block}.caption{text-align:center;font-size:1.25mm;color:#28738e;font-weight:bold;margin-top:.6mm}</style></head><body><table class="layout"><tbody>@foreach($students->chunk(2) as $pair)<tr>@foreach($pair as $student)@php $photo=$student->photo?storage_path('app/public/'.$student->photo):null;$logo=$school?->school_logo?storage_path('app/public/'.$school->school_logo):null;$photoData=($photo&&is_file($photo))?'data:image/'.strtolower(pathinfo($photo,PATHINFO_EXTENSION)).';base64,'.base64_encode(file_get_contents($photo)):null;$logoData=($logo&&is_file($logo))?'data:image/'.strtolower(pathinfo($logo,PATHINFO_EXTENSION)).';base64,'.base64_encode(file_get_contents($logo)):null;$qrData='data:image/svg+xml;base64,'.base64_encode(app(\App\Services\StudentBarcodeService::class)->svg($student,100));$birth=$student->birth_date?->translatedFormat('d M Y')?:'-'; @endphp<td class="slot {{$loop->iteration===2?'right':''}}"><div class="student-card"><div class="shape"></div><header class="header"><table class="tbl"><tr><td class="logo">@if($logoData)<img src="{{$logoData}}">@endif</td><td class="school"><b>{{$school?->school_name?:'Sistem Absensi Siswa'}}</b><small>{{$school?->school_address?:'Kartu identitas siswa sekolah'}}</small></td><td class="title"><b>KARTU SISWA</b><small>NOMOR INDUK SISWA NASIONAL</small></td></tr></table></header><section class="content"><table class="tbl"><tr><td>@if($photoData)<img class="photo" src="{{$photoData}}">@else<div class="photo"></div>@endif</td><td class="data"><table><tr><td>NISN</td><td>:</td><td>{{$student->nisn?:'-'}}</td></tr><tr><td>Nama</td><td>:</td><td>{{$student->name}}</td></tr><tr><td>Tempat Lahir</td><td>:</td><td>{{$student->birth_place?:'-'}}</td></tr><tr><td>Tanggal Lahir</td><td>:</td><td>{{$birth}}</td></tr><tr><td>Jenis Kelamin</td><td>:</td><td>{{$student->gender==='L'?'Laki-laki':'Perempuan'}}</td></tr></table></td><td class="qr"><div class="qrbox"><img src="{{$qrData}}"></div><div class="caption">SCAN ABSENSI</div></td></tr></table></section></div></td>@endforeach @if($pair->count()===1)<td class="slot right"></td>@endif</tr>@endforeach</tbody></table></body></html>
